// Deterministic pseudo-random in [0, 1), seeded by index — gives every curl a
// distinct wind amplitude/duration/delay without a server/client hydration
// mismatch (Math.random() would differ between SSR and the client render).
function seededRandom(seed: number): number {
  const x = Math.sin(seed * 12.9898) * 43758.5453;
  return x - Math.floor(x);
}

interface PortraitLogoProps {
  /** className applied to the outer wrapper (set width/height here). */
  className?: string;
  /** Stroke/fill colour. Defaults to currentColor so it inherits text colour. */
  color?: string;
  /** Re-run the full draw-in animation every time it re-enters view. */
  replayOnView?: boolean;
  /** Enable the cursor-tracking 3D tilt + glow effect. */
  tilt?: boolean;
}

export default function PortraitLogo({
  className = "",
  color = "currentColor",
  replayOnView = false,
  tilt = true,
}: PortraitLogoProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const isInView = useInView(containerRef, {
    once: !replayOnView,
    amount: 0.4,
  });

  const controls = useAnimation();
  const hasPlayedRef = useRef(false);

  // ---- cursor-tracking tilt + glow ------------------------------------------
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);
  const springConfig = { stiffness: 150, damping: 18, mass: 0.4 };
  const rotateX = useSpring(useTransform(mouseY, [-0.5, 0.5], [12, -12]), springConfig);
  const rotateY = useSpring(useTransform(mouseX, [-0.5, 0.5], [-12, 12]), springConfig);
  const glowX = useTransform(mouseX, [-0.5, 0.5], [0, 100]);
  const glowY = useTransform(mouseY, [-0.5, 0.5], [0, 100]);
  const glowBackground = useMotionTemplate`radial-gradient(circle at ${glowX}% ${glowY}%, rgba(130,130,255,0.28), transparent 60%)`;

  function handleMouseMove(e: MouseEvent<HTMLDivElement>) {
    if (!tilt || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    mouseX.set((e.clientX - rect.left) / rect.width - 0.5);
    mouseY.set((e.clientY - rect.top) / rect.height - 0.5);
  }

  function handleMouseLeave() {
    mouseX.set(0);
    mouseY.set(0);
  }

  // ---- orchestrated entrance sequence ---------------------------------------
  useEffect(() => {
    if (!isInView) return;
    if (hasPlayedRef.current && !replayOnView) return;

    let cancelled = false;

    const sequence = async () => {
      await controls.start("hidden");
      if (cancelled) return;
      await controls.start("silhouette");
      if (cancelled) return;
      await controls.start("curls");
      if (cancelled) return;
      await controls.start("settle");
      hasPlayedRef.current = true;
    };

    sequence();

    return () => {
      cancelled = true;
    };
  }, [isInView, controls, replayOnView]);

  return (
    <motion.div
      ref={containerRef}
      className={`group relative select-none [perspective:1200px] ${className}`}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      initial={{ opacity: 0, scale: 0.82, rotate: -6 }}
      animate={{ opacity: 1, scale: 1, rotate: 0 }}
      transition={{ duration: 0.9, ease: [0.22, 1, 0.36, 1] }}
      whileHover={{ scale: 1.035 }}
      whileTap={{ scale: 0.97 }}
      style={{
        rotateX: tilt ? rotateX : 0,
        rotateY: tilt ? rotateY : 0,
        transformStyle: "preserve-3d",
      }}
    >
      {/* cursor-follow ambient glow, purely decorative */}
      {tilt && (
        <motion.div
          aria-hidden
          className="pointer-events-none absolute -inset-6 -z-10 rounded-full opacity-0 blur-2xl transition-opacity duration-300 group-hover:opacity-100"
          style={{ background: glowBackground }}
        />
      )}

      {/* continuous slow idle float, independent of the draw-in sequence */}
      <motion.div
        animate={{ y: [0, -6, 0] }}
        transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }}
        className="h-full w-full"
      >
        <svg
          viewBox={VIEWBOX}
          xmlns="http://www.w3.org/2000/svg"
          className="h-full w-full overflow-visible"
          style={{ color }}
        >
          <defs>
            <clipPath id="portrait-reveal-clip">
              <motion.rect
                x={VB_X}
                y={VB_Y}
                width={VB_SIZE}
                initial="hidden"
                animate={controls}
                variants={{
                  hidden: { height: 0 },
                  silhouette: {
                    height: VB_SIZE,
                    transition: { duration: 1.1, ease: [0.65, 0, 0.35, 1] },
                  },
                  curls: { height: VB_SIZE },
                  settle: { height: VB_SIZE },
                }}
              />
            </clipPath>
          </defs>

          {/* --- filled silhouette, wiped in top-to-bottom --- */}
          <g clipPath="url(#portrait-reveal-clip)">
            <g transform={MAIN_TRANSFORM} fill={color} stroke="none">
              <path d={MAIN_PATH_D} />
            </g>
          </g>

          {/* --- hair curls, hand-drawn stroke by stroke --- */}
          <motion.g
            fill="none"
            stroke={color}
            strokeWidth={7}
            strokeLinecap="round"
            strokeLinejoin="round"
            initial="hidden"
            animate={controls}
          >
            {CURL_PATHS.map((d, i) => {
              // Each strand gets its own amplitude/speed/delay/direction so the
              // mass of curls reads as one continuous breeze rather than a
              // single mechanical oscillation — most lean the same way (a
              // prevailing wind direction), a minority counter-sway for
              // natural variance.
              const windAmplitude = 3 + seededRandom(i) * 5;
              const windDuration = 3 + seededRandom(i + 50) * 2.5;
              const windDelay = seededRandom(i + 100) * 2;
              const windSign = seededRandom(i + 150) < 0.75 ? 1 : -1;

              return (
                <motion.path
                  key={i}
                  d={d}
                  style={{ transformBox: "fill-box", transformOrigin: "50% 50%" }}
                  variants={{
                    hidden: { pathLength: 0, opacity: 0, rotate: 0 },
                    silhouette: { pathLength: 0, opacity: 0, rotate: 0 },
                    curls: {
                      pathLength: 1,
                      opacity: 1,
                      rotate: 0,
                      transition: {
                        pathLength: {
                          duration: 0.5,
                          ease: "easeInOut",
                          delay: i * 0.028,
                        },
                        opacity: { duration: 0.15, delay: i * 0.028 },
                      },
                    },
                    settle: {
                      pathLength: 1,
                      opacity: [1, 0.72, 1],
                      rotate: [0, windSign * windAmplitude, 0],
                      transition: {
                        opacity: {
                          duration: 2.4,
                          repeat: Infinity,
                          repeatType: "mirror",
                          ease: "easeInOut",
                          delay: i * 0.05,
                        },
                        rotate: {
                          duration: windDuration,
                          repeat: Infinity,
                          ease: "easeInOut",
                          delay: windDelay,
                        },
                      },
                    },
                  }}
                />
              );
            })}
          </motion.g>
        </svg>
      </motion.div>
    </motion.div>
  );
}
